package companion

// The log workbench follows New API's compact filter toolbar, inline statistics,
// dense data table, responsive cards, and per-request detail view.
const usageLogStyle = `<style>
.log-workbench{max-width:1340px;margin:0 auto}.log-head{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:24px}.log-head h1{margin:0;font-size:28px;font-weight:750;letter-spacing:-.035em}.log-head p{margin:5px 0 0;color:var(--muted);font-size:12px}.log-scope{display:inline-flex;gap:3px;padding:3px;border:1px solid var(--border);border-radius:9px;background:var(--surface)}.log-scope a{padding:6px 12px;border-radius:6px;color:var(--muted);font-size:12px;font-weight:600;text-decoration:none;white-space:nowrap}.log-scope a.active{background:#fff;color:var(--text);box-shadow:0 1px 3px rgba(45,42,38,.09)}
.log-toolbar{padding:13px;border:1px solid var(--border-strong);border-radius:12px;background:#fff;box-shadow:0 1px 3px rgba(45,42,38,.035)}.log-filter-grid{display:grid;grid-template-columns:minmax(280px,1.6fr) minmax(130px,1fr) minmax(132px,.75fr) auto;align-items:end;gap:9px}.log-field{display:grid;gap:5px;min-width:0}.log-field>span{color:var(--muted);font-size:10px;font-weight:700;letter-spacing:.04em}.log-field input,.log-field select{width:100%;min-width:0;height:35px;min-height:35px;padding:6px 10px;border:1px solid var(--border-strong);border-radius:7px;background:#fff;color:var(--text);font-size:12px}.log-field input:focus,.log-field select:focus{outline:none;border-color:#8b8680;box-shadow:0 0 0 3px rgba(139,134,128,.12)}.log-date-pair{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:7px}.log-date-pair>span{color:var(--quiet);font-size:12px}.log-more{position:relative;min-width:92px}.log-more summary{display:flex;align-items:center;justify-content:center;gap:6px;height:35px;padding:0 11px;border:1px solid var(--border-strong);border-radius:7px;color:var(--muted);font-size:12px;font-weight:600;white-space:nowrap;cursor:pointer;list-style:none}.log-more summary::-webkit-details-marker{display:none}.log-more summary::after{content:"⌄";font-size:15px;line-height:1;transform:translateY(-2px)}.log-more[open] summary{background:var(--surface);color:var(--text)}.log-more[open] summary::after{transform:rotate(180deg) translateY(2px)}.log-advanced{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-top:10px;padding-top:10px;border-top:1px solid var(--border)}.log-toolbar-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:11px;padding-top:11px;border-top:1px solid var(--border)}.log-stats{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.log-stat{display:inline-flex;align-items:center;gap:7px;height:27px;padding:0 9px;border:1px solid var(--border);border-radius:6px;background:var(--bg);font-size:11px;white-space:nowrap}.log-stat::before{content:"";width:3px;height:15px;border-radius:2px;background:#57aacf}.log-stat.rose::before{background:#ce7780}.log-stat.slate::before{background:#8e9aa5}.log-stat span{color:var(--muted)}.log-stat b{font:650 11px ui-monospace,SFMono-Regular,Menlo,monospace;font-variant-numeric:tabular-nums}.log-actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.log-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:33px;padding:0 11px;border:1px solid var(--border-strong);border-radius:7px;background:#fff;color:var(--text);font-size:11.5px;font-weight:600;text-decoration:none;white-space:nowrap;cursor:pointer}.log-btn:hover{background:var(--surface)}.log-btn.primary{border-color:var(--text);background:var(--text);color:#fff}.log-btn.primary:hover{background:#48443f}.log-btn:disabled{opacity:.5;cursor:not-allowed}.log-column-menu{position:relative}.log-column-menu summary{list-style:none}.log-column-menu summary::-webkit-details-marker{display:none}.log-column-menu[open] .log-column-popover{display:grid}.log-column-popover{position:absolute;z-index:10;right:0;top:calc(100% + 6px);display:none;gap:8px;min-width:160px;padding:12px;border:1px solid var(--border-strong);border-radius:9px;background:#fff;box-shadow:0 12px 28px rgba(45,42,38,.14)}.log-column-popover label{display:flex;align-items:center;gap:8px;font-size:11.5px;white-space:nowrap}.log-column-popover input{accent-color:var(--text)}
.log-table-shell{margin-top:15px;overflow:hidden;border:1px solid var(--border);border-radius:12px;background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.05)}.log-table-top{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:18px 20px;border-bottom:1px solid var(--border)}.log-table-top strong{font-size:16px;font-weight:700}.log-table-top span{color:var(--muted);font-size:11px}.log-table-scroll{overflow-x:auto}.logs-table{min-width:1060px}.logs-table td[data-col=time]{min-width:128px}.log-date{display:block;font:600 11px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap}.log-type{display:inline-flex;align-items:center;gap:5px;margin-top:5px;color:#087753;font-size:10px;font-weight:700}.log-type::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.log-type.error{color:#bb554a}.log-code{font:600 11px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.log-username{font-size:11.5px;font-weight:650;overflow-wrap:anywhere}.log-model{display:inline-block;max-width:220px;padding:4px 8px;border:1px solid var(--border);border-radius:6px;background:var(--bg);font-size:11px;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:middle}.log-sub{display:block;margin-top:4px;max-width:220px;color:var(--muted);font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.log-token{font:600 11px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap}.log-cache-rate{font:600 11px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap}.log-cost{font:700 11.5px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap}.log-time-metric{display:block;white-space:nowrap}.log-time-metric+.log-time-metric{margin-top:4px}.log-time-metric span{color:var(--muted);font-size:10px}.log-time-metric b{font:600 11px ui-monospace,SFMono-Regular,Menlo,monospace}.log-estimated{display:block;margin-top:3px;color:var(--muted);font-size:10px}.log-detail-btn{padding:5px 9px;border:1px solid var(--border-strong);border-radius:6px;background:#fff;color:var(--muted);font-size:11px}.log-detail-btn:hover{background:var(--surface);color:var(--text)}.log-empty{display:grid;place-items:center;min-height:215px;padding:30px;color:var(--muted);text-align:center;font-size:12px}.log-empty::before{content:"▤";display:block;margin-bottom:8px;color:var(--quiet);font-size:29px}.log-mobile-list{display:none}.log-pagination{display:flex;align-items:center;justify-content:flex-end;gap:10px;padding:12px 16px;border-top:1px solid var(--border);color:var(--muted);font-size:11px}.log-pagination a{padding:5px 9px;border:1px solid var(--border-strong);border-radius:6px;text-decoration:none}.log-pagination a:hover{background:var(--surface)}.log-note{margin:13px 0 0;color:var(--quiet);font-size:11px;line-height:1.6}
.log-dialog{width:min(560px,calc(100vw - 32px));padding:0;border:1px solid var(--border-strong);border-radius:14px;background:#fff;color:var(--text);box-shadow:0 20px 60px rgba(0,0,0,.2)}.log-dialog::backdrop{background:rgba(32,30,27,.46)}.log-dialog-head{display:flex;align-items:flex-start;justify-content:space-between;gap:15px;padding:14px 18px;border-bottom:1px solid var(--border)}.log-dialog-head h2{margin:0;font-size:16px}.log-dialog-head p{margin:4px 0 0;color:var(--muted);font-size:11px}.log-dialog-close{width:28px;height:28px;border:0;border-radius:6px;background:var(--surface);font-size:18px}.log-dialog-body{padding:4px 18px 16px}.log-detail-section{margin-top:10px}.log-detail-section h3{margin:0 0 5px;color:var(--muted);font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.log-detail-section dl{margin:0;border:1px solid var(--border);border-radius:8px;overflow:hidden}.log-detail-section dl>div{display:grid;grid-template-columns:120px minmax(0,1fr);gap:10px;padding:6px 10px;border-bottom:1px solid var(--border);font-size:11.5px}.log-detail-section dl>div:last-child{border:0}.log-detail-section dt{color:var(--muted)}.log-detail-section dd{margin:0;overflow-wrap:anywhere;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.log-detail-section .cost{font-weight:700}.log-duration-pair{display:flex;gap:16px;flex-wrap:wrap}.log-duration-pair span{white-space:nowrap}.log-duration-pair b{font-weight:600}
[hidden]{display:none!important}
@media(max-width:1050px){.log-filter-grid{grid-template-columns:minmax(250px,1.5fr) minmax(125px,1fr) minmax(115px,.8fr) auto}.log-advanced{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:720px){.log-head{align-items:flex-start;flex-direction:column}.log-toolbar{padding:11px}.log-filter-grid{grid-template-columns:1fr 1fr}.log-date-field{grid-column:1/-1}.log-more{grid-column:1/-1}.log-more summary{justify-content:flex-start}.log-toolbar-bottom{align-items:flex-start;flex-direction:column}.log-actions{width:100%}.log-actions .log-btn.primary{margin-left:auto}.log-table-scroll{display:none}.log-mobile-list{display:grid;gap:9px;padding:11px;background:var(--surface)}.log-mobile-card{padding:13px;border:1px solid var(--border);border-radius:9px;background:var(--bg)}.log-mobile-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.log-mobile-meta{display:flex;justify-content:space-between;gap:8px;margin:8px 0;color:var(--muted);font-size:10.5px}.log-mobile-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:9px;border-top:1px solid var(--border)}}
@media(max-width:470px){.log-filter-grid{grid-template-columns:1fr}.log-date-pair{grid-template-columns:1fr;gap:4px}.log-date-pair>span{display:none}.log-advanced{grid-template-columns:1fr}.log-stat{height:25px}.log-actions{gap:5px}.log-actions .log-btn{padding:0 8px}.log-detail-section dl>div{grid-template-columns:95px minmax(0,1fr)}}
@media(max-height:620px){.log-dialog-head{padding:10px 18px}.log-dialog-body{padding-bottom:10px}.log-detail-section{margin-top:7px}.log-detail-section h3{margin-bottom:4px}.log-detail-section dl>div{padding-top:4px;padding-bottom:4px}}
</style>`

const usageLogScript = `<script>
var advancedToggle=document.querySelector('.log-more');if(advancedToggle)advancedToggle.addEventListener('toggle',function(){document.querySelector('[data-advanced-filters]').hidden=!advancedToggle.open});
document.querySelectorAll('[data-log-detail]').forEach(function(button){button.addEventListener('click',function(){var dialog=document.getElementById(button.dataset.logDetail);if(dialog&&dialog.showModal)dialog.showModal()})});
document.querySelectorAll('[data-close-dialog]').forEach(function(button){button.addEventListener('click',function(){button.closest('dialog').close()})});
document.querySelectorAll('.log-dialog').forEach(function(dialog){dialog.addEventListener('click',function(event){if(event.target===dialog)dialog.close()})});
document.querySelectorAll('[data-column-toggle]').forEach(function(input){input.addEventListener('change',function(){document.querySelectorAll('[data-col="'+input.dataset.columnToggle+'"]').forEach(function(cell){cell.hidden=!input.checked})})});
var exportButton=document.querySelector('[data-export-page]');if(exportButton)exportButton.addEventListener('click',function(){var rows=[...document.querySelectorAll('.logs-table tr')].map(function(row){return [...row.querySelectorAll('th,td')].filter(function(cell){return !cell.hidden&&cell.dataset.col!=='detail'}).map(function(cell){return '"'+cell.innerText.replaceAll('"','""').replaceAll(String.fromCharCode(10),' ')+'"'}).join(',')});var blob=new Blob([String.fromCharCode(0xfeff)+rows.join(String.fromCharCode(13,10))],{type:'text/csv;charset=utf-8'});var link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='cpa-usage-logs-page.csv';link.click();setTimeout(function(){URL.revokeObjectURL(link.href)},1000)});
</script>`

const usageLogsTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>使用日志 · CPA Companion</title>` + pageStyle + usageLogStyle + `</head><body><div class="shell"><aside class="sidebar"><a class="brand" href="/dashboard"><span class="brand-mark">C</span><span class="brand-copy"><span class="brand-title">CPA Companion</span>` + brandVersionTemplate + `</span></a><nav class="nav"><span class="nav-label">工作台</span><a class="nav-link" href="/dashboard">仪表盘</a><a class="nav-link" href="/keys">我的密钥</a>{{if .Admin}}<a class="nav-link" href="/admin">分流方案</a><a class="nav-link" href="/audit">内容审计</a>{{end}}<a class="nav-link" href="/prices">模型价格</a><a class="nav-link active" aria-current="page" href="/logs">使用日志</a></nav>` + sidebarGitHubTemplate + `<div class="sidebar-footer"><div class="identity"><span class="avatar"><span class="avatar-fallback">C</span>{{if .User.AvatarURL}}<img src="{{.User.AvatarURL}}" alt="" referrerpolicy="no-referrer">{{end}}</span><span class="identity-copy"><span class="identity-name">{{.User.Username}}</span><span class="identity-meta">{{.User.ID}}</span></span></div><form method="post" action="/auth/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout">退出登录</button></form></div></aside><main class="content"><div class="log-workbench">
<header class="log-head"><div><h1>使用日志</h1><p>按请求查看模型、Token、费用和上游路由 · 北京时间</p></div>{{if .Admin}}<nav class="log-scope" aria-label="日志范围"><a href="{{.AllURL}}" class="{{if .All}}active{{end}}">全部用户</a><a href="{{.SelfURL}}" class="{{if not .All}}active{{end}}">仅看自己</a></nav>{{end}}</header>
<form class="log-toolbar" action="/logs" method="get">{{if .Admin}}<input type="hidden" name="scope" value="{{if .All}}all{{else}}self{{end}}">{{end}}<div class="log-filter-grid"><label class="log-field log-date-field"><span>时间范围 · 北京时间</span><span class="log-date-pair"><input type="datetime-local" name="start" value="{{.Start}}" aria-label="开始时间"><span>—</span><input type="datetime-local" name="end" value="{{.End}}" aria-label="结束时间"></span></label><label class="log-field"><span>模型</span><input name="model" value="{{.Model}}" placeholder="模型名称" autocomplete="off"></label><label class="log-field"><span>类型</span><select name="status" aria-label="请求类型"><option value="" {{if not .Status}}selected{{end}}>全部请求</option><option value="success" {{if eq .Status "success"}}selected{{end}}>成功</option><option value="error" {{if eq .Status "error"}}selected{{end}}>失败</option></select></label><details class="log-more" {{if or .UserFilter .KeyID .AccountID .Route}}open{{end}}><summary>更多筛选</summary></details></div><div class="log-advanced" data-advanced-filters {{if not (or .UserFilter .KeyID .AccountID .Route)}}hidden{{end}}>{{if and .Admin .All}}<label class="log-field"><span>用户 ID</span><input name="user" value="{{.UserFilter}}" placeholder="精确用户 ID" autocomplete="off"></label>{{end}}<label class="log-field"><span>API Key ID</span><input name="key" value="{{.KeyID}}" placeholder="精确密钥 ID" autocomplete="off"></label><label class="log-field"><span>上游账号 ID</span><input name="account" value="{{.AccountID}}" placeholder="精确账号 ID" autocomplete="off"></label><label class="log-field"><span>请求路径</span><input name="route" value="{{.Route}}" placeholder="例如 /v1/chat/completions" autocomplete="off"></label></div><div class="log-toolbar-bottom"><div class="log-stats" aria-label="当前筛选统计"><span class="log-stat"><span>费用</span><b>${{.Summary.CostUSD}}</b></span><span class="log-stat rose"><span>RPM</span><b>{{.Minute.Requests}}</b></span><span class="log-stat slate"><span>TPM</span><b>{{.Minute.TotalTokens}}</b></span></div><div class="log-actions"><a class="log-btn" href="{{.ResetURL}}">重置</a><button class="log-btn primary" type="submit">查询</button><button class="log-btn" type="button" data-export-page {{if not .Rows}}disabled{{end}}>导出本页</button><details class="log-column-menu"><summary class="log-btn" role="button">列设置 ▾</summary><div class="log-column-popover"><label><input type="checkbox" data-column-toggle="key" checked>API Key</label><label><input type="checkbox" data-column-toggle="account" checked>上游账号</label><label><input type="checkbox" data-column-toggle="tokens" checked>Token</label><label><input type="checkbox" data-column-toggle="cache-rate" checked>缓存命中率</label><label><input type="checkbox" data-column-toggle="cost" checked>费用</label><label><input type="checkbox" data-column-toggle="duration" checked>耗时</label></div></details></div></div></form>
{{if .LogID}}<p class="log-note">正在查看审计关联的请求日志 #{{.LogID}} · <a href="{{.ResetURL}}">返回全部日志</a></p>{{end}}<section class="log-table-shell"><div class="log-table-top"><strong>请求记录</strong><span>共 {{.Summary.Requests}} 条 · 每页最多 50 条</span></div>{{if .Rows}}<div class="log-table-scroll"><table class="logs-table"><thead><tr><th data-col="time">时间 / 状态</th>{{if .Admin}}<th data-col="user">用户名</th>{{end}}<th data-col="key">API Key</th><th data-col="model">模型 / 路径</th><th data-col="account">上游账号</th><th data-col="tokens">Token 输入 / 输出</th><th data-col="cache-rate">缓存命中率</th><th data-col="cost">费用</th><th data-col="duration">耗时</th><th data-col="detail">详情</th></tr></thead><tbody>{{range .Rows}}<tr><td data-col="time"><span class="log-date">{{.AtText}}</span><span class="log-type {{if not .Successful}}error{{end}}">{{if .Successful}}成功{{else}}失败 · {{.Status}}{{end}}</span></td>{{if $.Admin}}<td data-col="user"><span class="log-username">{{.Username}}</span></td>{{end}}<td data-col="key"><span class="log-code">{{if .KeyID}}{{.KeyID}}{{else}}—{{end}}</span></td><td data-col="model"><span class="log-model" title="{{.Model}}">{{if .Model}}{{.Model}}{{else}}—{{end}}</span><span class="log-sub" title="{{.Route}}">{{.Route}}</span></td><td data-col="account"><span class="log-code">{{if .AccountPrefix}}{{.AccountPrefix}}{{else}}—{{end}}</span></td><td data-col="tokens"><span class="log-token">{{.InputTokens}} / {{.OutputTokens}}</span>{{if or .CacheReadTokens .CacheWriteTokens}}<span class="log-sub">缓存 ↓{{.CacheReadTokens}} · ↑{{.CacheWriteTokens}}</span>{{end}}</td><td data-col="cache-rate"><span class="log-cache-rate">{{.CacheHitRateText}}</span></td><td data-col="cost"><span class="log-cost">${{.CostUSD}}</span>{{if .Estimated}}<span class="log-estimated">估算</span>{{end}}</td><td data-col="duration"><span class="log-time-metric"><span>首字 </span><b>{{.FirstByteText}}</b></span><span class="log-time-metric"><span>总耗时 </span><b>{{.DurationMS}} ms</b></span></td><td data-col="detail"><button type="button" class="log-detail-btn" data-log-detail="log-detail-{{.ID}}">查看</button></td></tr>{{end}}</tbody></table></div><div class="log-mobile-list">{{range .Rows}}<article class="log-mobile-card"><div class="log-mobile-top"><span class="log-model">{{if .Model}}{{.Model}}{{else}}—{{end}}</span><span class="log-cost">${{.CostUSD}}</span></div><div class="log-mobile-meta"><span><span class="log-type {{if not .Successful}}error{{end}}">{{if .Successful}}成功{{else}}失败 · {{.Status}}{{end}}</span><br>{{.AtText}}</span><span>{{.InputTokens}} / {{.OutputTokens}} Token<br>缓存命中率 {{.CacheHitRateText}}<br>首字 {{.FirstByteText}} · 总耗时 {{.DurationMS}} ms</span></div><div class="log-mobile-bottom"><span class="log-code">{{if $.Admin}}{{.Username}} · {{end}}{{if .AccountPrefix}}{{.AccountPrefix}}{{else}}—{{end}}</span><button type="button" class="log-detail-btn" data-log-detail="log-detail-{{.ID}}">查看详情</button></div></article>{{end}}</div>{{else}}<div class="log-empty"><div><strong>暂无使用日志</strong><div>调整筛选条件，或通过 API Key 发起请求后再查看。</div></div></div>{{end}}<div class="log-pagination">{{if .HasPrevious}}<a href="{{.PreviousURL}}">‹ 上一页</a>{{end}}<span>第 {{.Page}} / {{if .TotalPages}}{{.TotalPages}}{{else}}1{{end}} 页</span>{{if .HasNext}}<a href="{{.NextURL}}">下一页 ›</a>{{end}}</div></section>
{{range .Rows}}<dialog class="log-dialog" id="log-detail-{{.ID}}"><div class="log-dialog-head"><div><h2>请求详情</h2><p>日志 #{{.ID}} · {{.AtText}} · 北京时间</p></div><button class="log-dialog-close" type="button" data-close-dialog aria-label="关闭">×</button></div><div class="log-dialog-body"><section class="log-detail-section"><h3>请求</h3><dl><div><dt>状态</dt><dd>{{.Status}} · {{if .Successful}}成功{{else}}失败{{end}}</dd></div>{{if not .Successful}}<div><dt>错误码</dt><dd>{{.ErrorCodeText}}</dd></div><div><dt>错误消息</dt><dd>{{if .ErrorMessage}}{{.ErrorMessage}}{{else}}未记录{{end}}</dd></div>{{end}}<div><dt>模型</dt><dd>{{if .Model}}{{.Model}}{{else}}—{{end}}</dd></div><div><dt>路径</dt><dd>{{.Route}}</dd></div><div><dt>耗时</dt><dd class="log-duration-pair"><span>首字 <b>{{.FirstByteText}}</b></span><span>总耗时 <b>{{.DurationMS}} ms</b></span></dd></div></dl></section><section class="log-detail-section"><h3>路由</h3><dl><div><dt>用户名 / ID</dt><dd>{{.Username}} · {{.UserID}}</dd></div><div><dt>API Key ID</dt><dd>{{if .KeyID}}{{.KeyID}}{{else}}—{{end}}</dd></div><div><dt>方案 ID</dt><dd>{{if .PlanID}}{{.PlanID}}{{else}}—{{end}}</dd></div><div><dt>账号前缀</dt><dd>{{if .AccountPrefix}}{{.AccountPrefix}}{{else}}—{{end}}</dd></div></dl></section><section class="log-detail-section"><h3>用量与费用</h3><dl><div><dt>输入 Token</dt><dd>{{.InputTokens}}</dd></div><div><dt>输出 Token</dt><dd>{{.OutputTokens}}</dd></div><div><dt>缓存命中率</dt><dd>{{.CacheHitRateText}}</dd></div><div><dt>缓存读取</dt><dd>{{.CacheReadTokens}}</dd></div><div><dt>缓存写入</dt><dd>{{.CacheWriteTokens}}</dd></div><div><dt>费用 · USD</dt><dd class="cost">${{.CostUSD}}{{if .Estimated}} · 估算{{end}}</dd></div></dl></section></div></dialog>{{end}}<p class="log-note">仅保存请求元数据及失败响应的错误码、错误消息，不保存请求正文、完整响应正文或 API Key 明文。费用按请求完成时的模型价格记录。</p>
</div></main></div>` + selectControlScript + usageLogScript + navigationScript + `</body></html>`
